def _score(value: Any) -> float:
    if isinstance(value, bool) or not isinstance(value, (float, int)):
        raise NykraError("score must be a finite number")
    score = float(value)
    if not math.isfinite(score):
        raise NykraError("score must be a finite number")
    return score

